import sys, base64, hashlib

# secp256k1 parameters
P = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
A = 0
B = 7
Gx = 0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798
Gy = 0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8

def inv(a, m):
    return pow(a, -1, m)

def ec_add(p, q):
    if p is None: return q
    if q is None: return p
    x1,y1=p; x2,y2=q
    if x1==x2 and (y1+y2)%P==0: return None
    if p==q:
        m=(3*x1*x1)*inv(2*y1,P)%P
    else:
        m=(y2-y1)*inv(x2-x1,P)%P
    x3=(m*m-x1-x2)%P
    y3=(m*(x1-x3)-y1)%P
    return (x3,y3)

def ec_mul(k, p):
    r=None; a=p
    while k>0:
        if k&1: r=ec_add(r,a)
        a=ec_add(a,a)
        k>>=1
    return r

G=(Gx,Gy)

def hash256(b):
    return hashlib.sha256(hashlib.sha256(b).digest()).digest()

def ripemd160_sha256(b):
    h=hashlib.new('ripemd160')
    h.update(hashlib.sha256(b).digest())
    return h.digest()

B58=b'123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'

def b58encode(b):
    n=int.from_bytes(b,'big')
    s=b''
    while n>0:
        n,r=divmod(n,58)
        s=bytes([B58[r]])+s
    pad=0
    for c in b:
        if c==0: pad+=1
        else: break
    return b'1'*pad+s

def pubkey_to_address(x,y,compressed=True):
    if compressed:
        prefix=b'\x02' if y%2==0 else b'\x03'
        pub=prefix+x.to_bytes(32,'big')
    else:
        pub=b'\x04'+x.to_bytes(32,'big')+y.to_bytes(32,'big')
    h=ripemd160_sha256(pub)
    payload=b'\x00'+h
    chk=hash256(payload)[:4]
    return b58encode(payload+chk).decode()

def varint(n):
    if n<0xfd: return bytes([n])
    if n<=0xffff: return b'\xfd'+n.to_bytes(2,'little')
    if n<=0xffffffff: return b'\xfe'+n.to_bytes(4,'little')
    return b'\xff'+n.to_bytes(8,'little')

def msg_hash(msg):
    prefix=b'\x18Bitcoin Signed Message:\n'
    mb=msg.encode()
    data=prefix+varint(len(mb))+mb
    return hash256(data)

def sqrt_mod(a,p):
    return pow(a,(p+1)//4,p)

def recover_pubkey(sig, msg_h):
    if len(sig)!=65: return None
    header=sig[0]
    if header<27 or header>34: return None
    recid=(header-27)&3
    compressed=(header-27)>=4
    r=int.from_bytes(sig[1:33],'big')
    s=int.from_bytes(sig[33:65],'big')
    if r<=0 or r>=N or s<=0 or s>=N: return None
    x=r+(recid//2)*N
    if x>=P: return None
    alpha=(x*x*x+B)%P
    beta=sqrt_mod(alpha,P)
    if (beta*beta)%P!=alpha: return None
    if (beta%2)==(recid%2):
        y=P-beta
    else:
        y=beta
    R=(x,y)
    e=int.from_bytes(msg_h,'big')
    rinv=inv(r,N)
    sR=ec_mul(s,R)
    eG=ec_mul((-e)%N,G)
    Q=ec_add(sR,eG)
    if Q is None: return None
    Q=(rinv*1%N, 0)
    # actually: Q = rinv * (sR + eG)
    sR=ec_mul(s,R)
    eG=ec_mul((-e)%N,G)
    sum_pt=ec_add(sR,eG)
    if sum_pt is None: return None
    Q=ec_mul(rinv,sum_pt)
    if Q is None: return None
    return Q, compressed

def main():
    data=sys.stdin.read().split('\n')
    if len(data)<3:
        print('INVALID'); return
    addr=data[0].strip()
    msg=data[1]
    sig_b64=data[2].strip()
    try:
        sig=base64.b64decode(sig_b64,validate=True)
    except Exception:
        print('INVALID'); return
    h=msg_hash(msg)
    try:
        res=recover_pubkey(sig,h)
    except Exception:
        print('INVALID'); return
    if res is None:
        print('INVALID'); return
    (x,y),compressed=res
    derived=pubkey_to_address(x,y,compressed)
    print('VALID' if derived==addr else 'INVALID')

main()
